css:
.lf{counter-reset:loc}
.lf__filters{display:flex;flex-direction:column;gap:10px;align-items:flex-start;margin-bottom:var(--space-5)}
.lf__chips{display:flex;gap:var(--space-2);flex-wrap:wrap}
.lf__chip{display:inline-flex;align-items:center;min-height:34px;padding:0 14px;border:1px solid var(--line);border-radius:var(--radius-nav);background:var(--card);color:var(--ink);font-size:var(--text-eyebrow);font-weight:600;cursor:pointer;transition:background-color .15s ease}
.lf__chip:hover{background:var(--paper)}
.lf__chip[aria-pressed="true"]{background:var(--ink);border-color:transparent;color:#fff}
.lf__count{margin:0 0 var(--space-4);font-size:var(--text-small);font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.lf__rail{display:flex;gap:var(--space-4);overflow-x:auto;padding-bottom:var(--space-2);scroll-snap-type:x mandatory}
.lf__card{counter-increment:loc;flex:0 0 268px;scroll-snap-align:start;background:var(--card);border:1px solid var(--line);border-radius:var(--radius-card);padding:var(--space-5)}
.lf__card[hidden]{display:none}
.lf__head{display:flex;justify-content:space-between;align-items:baseline;gap:10px;margin-bottom:6px}
.lf__name{margin:0;font-family:var(--font-heading);font-weight:700;font-size:17px;line-height:1.25;text-transform:uppercase;letter-spacing:.01em;color:var(--ink)}
.lf__name::before{content:counter(loc,decimal-leading-zero) " ";color:var(--muted);font-size:var(--text-small)}
.lf__state{flex-shrink:0;font-weight:700;font-size:var(--text-small);color:var(--muted)}
.lf__address{font-size:var(--text-small);line-height:1.5;color:var(--muted);margin-bottom:var(--space-3)}
.lf__phone{font-size:var(--text-small);margin-bottom:var(--space-4);color:var(--ink)}
.lf__directions{display:inline-block;font-size:var(--text-small);font-weight:700;color:var(--accent-dark);text-decoration:none;margin-bottom:18px}
.lf__directions:hover{text-decoration:underline}
.lf__tags{display:flex;gap:var(--space-2);flex-wrap:wrap}
.lf__tag{display:inline-flex;align-items:center;height:24px;padding:0 10px;border-radius:var(--radius-chip);background:var(--paper);border:1px solid var(--line);font-size:var(--text-eyebrow);font-weight:700;color:var(--muted)}
.lf__empty{padding:var(--space-6) 0;color:var(--muted);font-size:var(--text-small)}
@media (max-width:900px){.lf__filters{align-items:stretch}.lf__chips{flex-wrap:nowrap;overflow-x:auto}.lf__chip{flex:0 0 auto;white-space:nowrap}}
